svg:
.container {
background-color: #0d1117;
border: 1px solid #30363d;
border-radius: 12px;
padding: 20px;
color: #c9d1d9;
font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif, "Apple Color Emoji";
box-shadow: 0 8px 24px rgba(0,0,0,0.5);
box-sizing: border-box;
height: 350px;
}
.header {
display: flex;
align-items: center;
margin-bottom: 20px;
}
.dot { width: 12px; height: 12px; border-radius: 50%; margin-right: 8px; display: inline-block; }
.red { background: #ff5f56; }
.yellow { background: #ffbd2e; }
.green { background: #27c93f; }
.title { color: #8b949e; font-size: 13px; margin-left: auto; margin-right: auto; font-family: monospace; }
.prompt { color: #58a6ff; font-family: monospace; font-size: 14px; margin-bottom: 6px; }
.name { color: #f0f6fc; font-size: 28px; font-weight: 800; margin: 0 0 6px 0; }
.job-title {
font-size: 18px;
font-weight: 700;
background: linear-gradient(90deg, #58a6ff, #3fb950);
-webkit-background-clip: text;
-webkit-text-fill-color: transparent;
margin-bottom: 8px;
font-family: monospace;
}
.cursor {
display: inline-block;
width: 8px;
height: 18px;
background-color: #3fb950;
vertical-align: middle;
animation: blink 1s infinite;
}
@keyframes blink { 0%, 100% { opacity: 1; } 50% { opacity: 0; } }
.desc { color: #8b949e; font-size: 14px; margin-bottom: 18px; }
.stats-grid {
display: grid;
grid-template-columns: repeat(3, 1fr);
gap: 12px;
background: #161b22;
padding: 12px;
border-radius: 8px;
border: 1px solid #21262d;
text-align: center;
}
.stat-val { font-size: 18px; font-weight: bold; color: #58a6ff; }
.stat-lbl { font-size: 11px; color: #8b949e; margin-top: 2px; }

